from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    total_sum = sum(numbers)
    total_product = 1
    for number in numbers:
        total_product *= number
    if not numbers:
        total_product = 1  # set product to 1 if the list is empty
    return total_sum, total_product

def fizz_buzz(n: int):
    count = 0
    seen_count = {}
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            if i not in seen_count:
                seen_count[i] = str(i).count('7')
                count += seen_count[i]
    return count

def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing."""
    if len(l) < 2:
        return True
    increasing = decreasing = True
    for i in range(1, len(l)):
        if l[i] > l[i - 1]:
            decreasing = False
        elif l[i] < l[i - 1]:
            increasing = False
    return increasing or decreasing

def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    largest_factor = 1
    # Check for number of 2s that divide n
    while n % 2 == 0:
        largest_factor = 2
        n //= 2
    # n must be odd at this point, so we can skip even numbers
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            largest_factor = i
            n //= i
    # This condition is to check if n is a prime number greater than 2
    if n > 2:
        largest_factor = n
    return largest_factor

def correct_bracketing(brackets: str):
    balance = 0
    for char in brackets:
        if char == '(':  
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def numerical_letter_grade(grades):
    result = []
    for grade in grades:
        if grade == 4.0:
            result.append('A+')
        elif grade > 3.7:
            result.append('A')
        elif grade > 3.3:
            result.append('A-')
        elif grade > 3.0:
            result.append('B+')
        elif grade > 2.7:
            result.append('B')
        elif grade > 2.3:
            result.append('B-')
        elif grade > 2.0:
            result.append('C+')
        elif grade > 1.7:
            result.append('C')
        elif grade > 1.3:
            result.append('C-')
        elif grade > 1.0:
            result.append('D+')
        elif grade > 0.7:
            result.append('D')
        elif grade > 0.0:
            result.append('D-')
        else:
            result.append('E')
