def anti_shuffle(s):
    words = s.split(' ')
    sorted_words = [''.join(sorted(word)) for word in words]
    return ' '.join(sorted_words)

def words_string(s):
    import re
    return [word for word in re.split(r'[ ,]+', s.strip()) if word]

def minPath(grid, k):
    from heapq import heappop, heappush

    N = len(grid)
    # Find the minimum value and its position
    min_value = float('inf')
    start_positions = []
    for i in range(N):
        for j in range(N):
            if grid[i][j] < min_value:
                min_value = grid[i][j]
                start_positions = [(i, j)]
            elif grid[i][j] == min_value:
                start_positions.append((i, j))

    # Directions for moving up, down, left, right
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # We will use a priority queue to find the lexicographically smallest path
    pq = []
    for pos in start_positions:
        heappush(pq, ([grid[pos[0]][pos[1]]], pos))  # (path, position)

    # Generate paths
    while pq:
        path, (x, y) = heappop(pq)
        if len(path) == k:
            return path
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                heappush(pq, (path + [grid[nx][ny]], (nx, ny)))

    return []

def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""
    return n >= 8 and n % 2 == 0

def sum_squares(lst):
    total = 0
    for i, value in enumerate(lst):
        if i % 3 == 0:
            total += value ** 2
        if i % 4 == 0 and i % 3 != 0:
            total += value ** 3
        if i % 3 != 0 and i % 4 != 0:
            total += value
    return total

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))
    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def x_or_y(n, x, y):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True
    return x if is_prime(n) else y

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not isinstance(text, str):
        raise TypeError("Input must be a string.")
    if text == '':
        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()
